export const JOB_MARKET_DATA = {professions: [{profession: "Accountant",category: "Finance & Accounting",hookAngle: "I am writing to express my interest in the Accountant position, where I can apply my expertise in streamlining closing cycles and maintaining audit-ready fiscal records.",reframe: "I focus on transforming transactional data into a clear foundation for strategic fiscal health and institutional trust.",powerWords: ["P&L Integrity", "Reconciliation"],bridgeSkills: ["General Ledger", "Statutory Reporting", "Tax Compliance"],toneDefault: "formal",keywords: ["IFRS", "GAAP", "Vouching", "Trial Balance", "Financial Statements"]},{profession: "Software Engineer",category: "Technology & Data",hookAngle: "With a focus on building resilient, scalable systems, I am eager to contribute to your engineering team as a Software Engineer.",reframe: "I bridge the gap between complex business requirements and high-performance codebases that power growth.",powerWords: ["System Architecture", "Scalability"],bridgeSkills: ["Full-stack Development", "Agile", "Unit Testing"],toneDefault: "performance",keywords: ["JavaScript", "Python", "Cloud Computing", "SDLC", "System Design"]},{profession: "Sales Executive",category: "Sales & BD",hookAngle: "I am excited to apply for the Sales Executive position, bringing a proven track record of revenue growth and persistent prospecting.",reframe: "I convert cold leads into high-value accounts through value-based selling and relationship management.",powerWords: ["Quota Attainment", "Lead Conversion"],bridgeSkills: ["Cold Calling", "Negotiation", "CRM Management"],toneDefault: "performance",keywords: ["B2B Sales", "Sales Pipeline", "Inside Sales", "Closing", "Account Management"]},{profession: "Human Resources Manager",category: "HR & People",hookAngle: "I am writing to express my interest in the Human Resources Manager role, where I can optimize human capital and employee advocacy.",reframe: "I synchronize organizational policies with employee wellbeing to drive retention and operational harmony.",powerWords: ["Employee Relations", "Compliance"],bridgeSkills: ["Policy Development", "Conflict Resolution", "Admin Support"],toneDefault: "formal",keywords: ["Employee Engagement", "Onboarding", "Labor Law", "HRIS", "Performance Management"]},{profession: "Project Manager",category: "Engineering & Construction",hookAngle: "With a focus on delivering complex projects on time and under budget, I am eager to join your team as a Project Manager.",reframe: "I synchronize diverse workstreams to deliver complex projects while maintaining strict budget controls.",powerWords: ["Milestone Tracking", "Resource Allocation"],bridgeSkills: ["Risk Mitigation", "Budget Management", "Vendor Coordination"],toneDefault: "performance",keywords: ["PMP", "Prince2", "Gantt Charts", "Procurement", "Agile"]}],aliases: {"Finance & Accounting": ["Bookkeeper", "Controller", "Tax Manager", "Auditor", "Banking"],"Technology & Data": ["Web Developer", "System Admin", "QA Engineer", "Frontend", "Backend", "Data Analyst"],"Sales & BD": ["Account Manager", "Business Development", "Real Estate", "Broker"],"HR & People": ["Recruiter", "People Ops", "L&D Specialist"],"Engineering & Construction": ["Civil Engineer", "Site Engineer", "Architect"]}};function cleanRole(role) {if (!role) return "";return role.replace(/position|role|job|opening|vacancy/gi, "").replace(/\s\s+/g, " ").trim();}function extractRole(jobTitle) {const raw = jobTitle || "";const cleaned = cleanRole(raw);/* 7-step fallback chain */if (!cleaned) return "this role";const segments = cleaned.split(/for|at|in|with/i);if (segments[0].trim().length > 3) return segments[0].trim();return cleaned;}function getProfession(title) {const target = (title || "").toLowerCase().trim();const match = JOB_MARKET_DATA.professions.find(p => p.profession.toLowerCase() === target);if (match) return match;for (const [category, aliases] of Object.entries(JOB_MARKET_DATA.aliases)) {if (aliases.some(alias => target.includes(alias.toLowerCase()))) {return JOB_MARKET_DATA.professions.find(p => p.category === category) || JOB_MARKET_DATA.professions[0];}}return JOB_MARKET_DATA.professions[0];}function getImpact(experience) {if (!experience || !experience[0]) return "";const desc = experience[0].description || (experience[0].points ? experience[0].points[0] : "");if (!desc) return "";const firstSentence = desc.split('.')[0];return firstSentence.replace(/responsible for|managed|handled|worked on/gi, "driving").replace(/tasks include|duties were/gi, "outcomes such as").trim();}export function transformRawInput(rawInput, targetRole) {if (!rawInput) return null;const cleanedRole = extractRole(targetRole);const input = rawInput.toLowerCase();/* Transition logic */if (input.includes("change") || input.includes("switch") || input.includes("want to become")) {return `Currently transitioning into ${cleanedRole}, I am leveraging my background to bring a fresh, results-oriented perspective to your team. My recent focus has been on mastering the specific financial and operational nuances required to excel in this sector.`;}/* Experience pivot logic */if (input.includes("years") || input.includes("dealt with") || input.includes("gained")) {const highlights = rawInput.replace(/i am|i have|i've/gi, "").trim();return `With a background characterized by ${highlights}, I have developed a sophisticated understanding of client needs and high-stakes environments. I am now looking to apply this expertise directly to the objectives at your organization.`;}return rawInput;}export function generateCoverLetterFromTemplate(formData, cvData) {const { jobTitle = "this role", companyName = "your organization", region = "GCC", selfDescription = "" } = formData;const { fullName = "Candidate", experience = [], skills = [] } = cvData;const prof = getProfession(jobTitle);const isIndia = region === "India";const targetRole = extractRole(jobTitle);/* Paragraph 1: Value-led Opening */const opening = isIndia ? `I am submitting my application for the ${targetRole} position, bringing a dedicated approach to ${prof.powerWords[0].toLowerCase()} that aligns with ${companyName}’s current growth trajectory.` : `I am writing to move forward with the ${targetRole} opening at ${companyName}, where I can immediately apply my track record in ${prof.powerWords[0].toLowerCase()} to support your team’s objectives.`;/* Paragraph 2: Human Connection (Smart logic) */const generatedBody = transformRawInput(selfDescription, jobTitle);const impactStatement = getImpact(experience);const userSkills = skills.slice(0, 3).join(", ");let connection = "";if (generatedBody) {connection = generatedBody;} else {const skillText = userSkills ? `built on a high-performance blend of ${userSkills}` : `centered on ${prof.bridgeSkills[0].toLowerCase()}`;connection = isIndia ? `With a foundation ${skillText}, I have focused my career on ${prof.bridgeSkills[0].toLowerCase()} to ensure consistent delivery. ${impactStatement ? `My recent work involved ${impactStatement.toLowerCase()}, which has prepared me for the challenges of this role.` : ""}` : `My professional toolkit is ${skillText}. ${impactStatement ? `Specifically, my experience ${impactStatement.toLowerCase()} allows me to hit the ground running at ${companyName}.` : ""}`;}/* Paragraph 3: The "Why" Closer */const closer = isIndia ? `${prof.reframe} I am eager to contribute to ${companyName}’s long-term vision and would appreciate the opportunity to discuss how my qualifications meet your requirements.` : `${prof.reframe} I admire ${companyName}’s positioning in the market and am confident that my focus on ${prof.powerWords[1].toLowerCase()} makes me a strong fit for your culture.`;/* Geolocation Assembly */const salutation = isIndia ? "Dear Sir/Madam," : "Dear Hiring Manager,";const signOff = isIndia ? "Yours sincerely," : "Warm regards,";const letter = [salutation,opening,connection,closer,signOff,fullName].join("\n\n");return letter.replace(/$$.*?$$/g, "").replace(/\s\s+/g, " ").replace(/position position/gi, "position").replace(/role role/gi, "role").trim();}